(function(g){
'use strict';
const E=g.PCGEngine,C=g.PCGContent,S=g.PCGStore,A=g.PCGAssets,P=C.pack,D=Object.fromEntries(P.cards.map(c=>[c.template_id,c])),T=C.presentation;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=v=>JSON.parse(JSON.stringify(v));
const app=$('#app'),modal=$('#modal'),HASH=E.digest(P),id=()=>S.uuid();
function getRememberedPlayer(){try{return sessionStorage.getItem('pcg.selected');}catch(e){return null;}}
function rememberPlayer(){try{sessionStorage.setItem('pcg.selected',profileId);}catch(e){/* Selected tab identity is optional; progress still uses the validated local store. */}}
let db,profileId=getRememberedPlayer()||null,screen='home',mode=null,authority=null,view=null,identities=[],seat=0,unlocked=null,selected=null,selectedRow=null,selectedTarget=null,busy=false,logs=[],matchEvents=[],aiTimer=null,network=null,netInfo={state:'idle',message:'尚未连接'},netOutput='',netOutputKind='',netRole=null,netLocal=null,readerInfo={state:'disconnected',source:null,message:'未连接读卡器',canWrite:false},lastScan=null,registration=null,draftSkin='01',draftDeck=null,collectionTab='all',profileAfter=null,toastTimer,aiBlocked=false,netIceMode='public',netIceText='';
const names={'01':'S3','02':'StickS3','03':'AI PYRAMID PRO','04':'Console','05':'Ring','06':'VoiceS3R ATOM','07':'NanoH2','08':'DUALKEY','09':'StackChan'};
const friendly={NOT_YOUR_TURN:'现在不是你的回合',STALE_REVISION:'战场状态已更新，请重新选择',NO_TACTIC_TARGET:'战场上还没有这张战术牌的目标',TARGET_REQUIRED_OR_INVALID:'请先点选一个有效目标',ILLEGAL_ROW:'这个角色不能放在这一排',MATCH_FINISHED:'这场对战已经结束',ACTION_ID_CONFLICT:'动作编号冲突，请重新操作',CONTENT_MISMATCH:'双方卡包不同，请使用同一版本'};
function message(e){return friendly[e?.code]||friendly[e?.message]||e?.message||String(e);}
function toast(text,error=false){const t=$('#toast');t.textContent=text;t.className=(error?'error ':'')+'show';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',error?6500:4200);}
function fail(e){console.error(e);toast(message(e),true);}
function current(){return profileId?db.getProfile(profileId):null;}
function publicProfile(p){return{player_id:p.player_id,name:p.nickname,skin:p.extensions.web.skin,simulated:p.extensions.web.simulated};}
function avatar(p,cls='avatar'){return `<img class="${cls}" src="${A['char'+(p?.skin||'01')]}" alt="${esc(names[p?.skin||'01'])}">`;}
function btn(action,label,cls='',extra=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function modalOpen(title,html,wide=false,kicker='PULSE / 触卡对决'){modal.className=wide?'wide':'';modal.innerHTML=`<div class="modal-head"><div><div class="eyebrow">${kicker}</div><h2 id="modal-title">${title}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="关闭">×</button></div>${html}`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();registration=null;}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function effectText(c){const op=c.effect.op;if(op==='BOOST')return'部署：一名己方角色 +2';if(op==='DAMAGE')return'部署：一名敌方角色 −2';if(op==='SELF_BOOST_OTHER_ROW')return'部署时另一排有友军，自身 +2';if(c.traits.includes('stable'))return'稳定：战力不受任何修改';if(c.traits.includes('shield_once'))return'护盾：抵消首次受到的干扰';return'无技能 · 可靠的基础战力';}
function rowLabel(c){return c.kind==='tactic'?'战术':c.allowed_rows.length===2?'前排 / 后排':c.allowed_rows[0]==='front'?'前排':'后排';}
function cardHTML(tid,{action='',instance='',selected:chosen=false,owned=false,small=false,disabled=false}={}){const c=D[tid],t=T[tid];if(!c)return'';const p=current(),item=p?.collection.find(i=>i.template_id===tid),ink=item?.skin_id==='ink';return `<button type="button" class="game-card ${t.rarity} ${c.effect.op==='DAMAGE'?'damage':''} ${chosen?'selected':''} ${ink?'ink':''}" ${action?`data-action="${action}" data-id="${esc(instance||tid)}"`:''} ${disabled?'disabled':''} aria-label="${esc(t.name+'，'+(c.kind==='unit'?c.base_power+' 战力，':'')+effectText(c))}"><div class="card-top"><span class="power">${c.kind==='unit'?c.base_power:c.effect.op==='BOOST'?'+2':'−2'}</span><span class="card-id">${t.asset?'M5 / '+t.asset:'TACTIC'}</span></div><div class="card-art">${t.asset?`<img src="${A['char'+t.asset]}" alt="${esc(t.name)}" draggable="false">`:`<span class="tactic-art">${c.effect.op==='BOOST'?'⌁':'⌁'}</span>`}</div><div class="card-info"><div class="card-name">${esc(t.name)}</div><div class="card-effect">${effectText(c)}</div><div class="card-footer"><span>${rowLabel(c)}</span><span>${c.traits.includes('stable')?'◆ 稳定':c.traits.includes('shield_once')?'◇ 护盾':t.rarity==='hero'?'★ 英雄':c.kind==='tactic'?'↗ 指令':'● 角色'}</span></div></div><div class="card-bottom-stripe"></div></button>`;}
function header(){const p=current();return`<header class="topbar"><button class="brand" data-action="nav" data-page="home" aria-label="PULSE 首页"><span class="brand-mark"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M2 13h5l3-7 4 13 3-6h5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span><span class="brand-name">PULSE</span><div class="brand-sub">触卡对决 / CARD BATTLE</div></span></button><nav class="nav" aria-label="主导航"><button class="${['home','battle','network'].includes(screen)?'active':''}" data-action="nav" data-page="home">对战大厅</button><button class="${screen==='collection'?'active':''}" data-action="nav" data-page="collection">我的卡牌</button><button class="desktop-nav ${screen==='readers'?'active':''}" data-action="nav" data-page="readers">读卡器</button></nav><div class="top-right"><button class="connection" data-action="nav" data-page="readers" style="background:none"><i class="dot ${g.PCGReaders.lampOn(readerInfo.state)?'on':''}"></i><span id="reader-state">${esc(g.PCGReaders.connectionLabel(readerInfo.state))}</span></button><button class="profile-pill" data-action="players">${p?avatar(publicProfile(p)):avatar({skin:'09'})}<span>${p?esc(p.nickname):'刷卡登录'}</span><span class="pill-arrow">⌄</span></button></div></header>`;}
function wikiHref(){const path=location.pathname;return /\/dist\/(?:index\.html)?$/.test(path)?'../wiki/index.html':'wiki/index.html';}
function clashHref(){const path=location.pathname;return /\/dist\/(?:index\.html)?$/.test(path)?'clash/index.html':'dist/clash/index.html';}
function home(){const p=current();let resume=db.data.saved_match?.state.phase==='playing';return`<main class="page"><section class="home-intro"><div class="home-copy"><span class="eyebrow">NFC × TACTICAL CARD GAME</span><h1>落一张牌，<br>留<span>一手。</span></h1><p>唤醒你手中的 M5 伙伴。用十张牌、两条战线，打赢一场关于时机与取舍的对决。</p><div class="actions">${btn('start-ai','开始一场练习　↗','primary')}${btn('rules','玩法说明','ghost')}<a class="btn ghost" href="${wikiHref()}" style="text-decoration:none">卡牌图鉴</a><a class="btn light" href="${clashHref()}" style="text-decoration:none">回合战</a></div><div class="feature-line"><span><b>10</b> 张起手牌</span><span><b>3</b> 局定胜负</span><span><b>5</b> 分钟的博弈</span></div></div><div class="hero-collage" aria-label="M5STACK 角色卡展示"><div class="hero-word">PULSE</div><div class="hero-circle"></div><div class="hero-card first">${cardHTML('paper_archive')}</div><div class="hero-card second">${cardHTML('core2_anchor')}</div><div class="hero-stamp"><span style="font-size:24px;color:var(--mint)">◎</span><span><strong>轻轻一碰，伙伴到场。</strong>NFC CARD · 10–22 HEROES</span></div></div></section><div class="section-label">Choose your battlefield / 选择你的战场</div><section class="mode-grid"><button class="mode-card" data-action="start-ai"><span class="mode-icon">⌘</span><div><h3>训练场 <span class="badge gray">单人</span></h3><p>和会留牌的电脑交手。<br>无需读卡器，即刻试玩。</p></div><span class="mode-arrow">↗</span></button><button class="mode-card" data-action="hotseat"><span class="mode-icon">⇄</span><div><h3>面对面对决 <span class="badge gold">本地双人</span></h3><p>一台设备，两张玩家卡。<br>交接设备，刷卡揭开手牌。</p></div><span class="mode-arrow">↗</span></button><button class="mode-card" data-action="online"><span class="mode-icon">⌁</span><div><h3>远程交锋 <span class="badge gray">WebRTC</span></h3><p>交换连接码，直接对战。<br>浏览器之间，无需游戏服务器。</p></div><span class="mode-arrow">↗</span></button></section>${resume?`<div class="notice" style="margin-top:18px"><div class="spread"><span>发现一场未完成的${db.data.saved_match.mode==='ai'?'训练':'本地双人'}对局。刷新前的回合已经保存在这台浏览器。</span>${btn('resume','继续对局','small green')}</div></div>`:''}<div class="bottom-info"><span>${p?`${esc(p.nickname)} · 已收集 ${p.collection.length}/13 位伙伴 · ${p.wallet.shards} 碎片`:'先试玩，再刷卡。角色数值不会随着抽卡次数变强。'}<br><span>离线可玩 · 浏览器本地存档 · 玩家卡 01–09 / 英雄卡 10–22</span></span><button class="textlink" data-action="simcards">打开模拟卡盒 ↗</button></div></main>`;}
function collection(){const p=current();if(!p)return`<main class="page"><div class="page-heading"><div><div class="eyebrow">COLLECTION</div><h1>你的伙伴，等你来唤醒。</h1><p>先刷玩家卡登录，再刷英雄卡领取角色。</p></div></div>${btn('players','刷卡登录 / 创建模拟玩家','primary')}</main>`;if(!draftDeck)draftDeck=p.decks[0].template_ids.slice();const owned=p.collection.map(c=>c.template_id),cards=P.cards.filter(c=>collectionTab==='all'||collectionTab==='owned'&&owned.includes(c.template_id)||collectionTab==='deck'&&draftDeck.includes(c.template_id));return`<main class="page"><div class="page-heading"><div><div class="eyebrow">THE COLLECTION / 我的编队</div><h1>把每张牌，用在对的时候。</h1><p>标准对战可借用全部角色。刷卡得到自己的收藏，重复角色转为外观碎片。</p></div><div class="actions"><span class="badge gold">${owned.length} / 13 已收藏</span><span class="badge">◇ ${p.wallet.shards} 碎片</span>${btn('simcards','刷英雄卡','small primary')}</div></div><div class="collection-filter"><div class="tabs">${[['all','全部 15'],['owned','已收藏 '+owned.length],['deck','编队 '+draftDeck.length]].map(([v,t])=>`<button class="${collectionTab===v?'active':''}" data-action="collection-tab" data-value="${v}">${t}</button>`).join('')}</div><span class="hint">点击卡牌查看详情；下方按钮加入或移出编队。</span></div><div class="card-grid">${cards.map(c=>`<div class="collection-item">${cardHTML(c.template_id,{action:'card-detail'})}<div class="collection-tools"><span class="badge ${owned.includes(c.template_id)?'gold':'gray'}">${c.kind==='tactic'?'公共战术':owned.includes(c.template_id)?'已拥有':'标准借用'}</span><button class="deck-indicator ${draftDeck.includes(c.template_id)?'selected':''}" data-action="toggle-deck" data-id="${c.template_id}">${draftDeck.includes(c.template_id)?'✓ 已编入':'＋ 编入'}</button></div></div>`).join('')}</div>${!cards.length?'<div class="scan-well"><h3>收藏，从一次碰卡开始。</h3><p class="hint">打开模拟卡盒，也可以先试试每日盲盒。</p></div>':''}<div class="deck-bar"><div><strong>当前编队　${draftDeck.length} / 10</strong><p>至少 6 名角色 · 同名卡限 1 张 · 全部手牌跨局共用</p></div><div class="actions">${btn('reset-deck','推荐编队','small ghost')}${btn('save-deck','保存编队','small primary',S.validDeck(draftDeck)?'':'disabled')}</div></div></main>`;}
function rules(){modalOpen('赢下两局，或学会放弃一局。',`<p class="modal-copy">每一局比的是两排角色的战力总和；整场比的是你如何花掉仅有的十张牌。</p><div class="rule-steps">${[['01','十张牌，贯穿整场','开局十张全在手上，局间不补牌。已出角色在本局结算后弃置，没出的牌留到下一局。'],['02','每回合一张牌，最多五张','选手牌 → 选择前排或后排 → 有技能时点选目标 → 部署。出满五张，或没牌时，自动结束本局出牌。'],['03','PASS 是战术，不是认输','点“本局停牌”后本局不能再出牌；对方可以继续。双方都停牌才比较总战力。适时放掉一局，把强牌留在手里。'],['04','三局内结算整场','胜局得 2 分，平局双方各 1 分。先到 4 分结束；否则第三局结束比积分，同分可平局。上一局胜者先手，平局则轮换先手。'],['05','两排不是装饰','有些角色只能部署在指定排。“联结”角色在另一排已有友军时，自身 +2。“稳定”不受任何战力修改，“护盾”抵消一次干扰。']].map(([n,h,p])=>`<div class="rule-step"><span class="step-num">${n}</span><div><strong>${h}</strong><p>${p}</p></div></div>`).join('')}</div><div class="notice">抽卡不会升级战力。标准对战允许借用全部角色；重复角色给 10 碎片，50 碎片可解锁墨色外观。</div><div class="spacer"></div>${btn('close-modal','明白，留一手。','full primary')}`,false,'HOW TO PLAY / 玩法');}
function players(after=null){profileAfter=after;const ps=db.profiles;modalOpen('先碰一下，你的玩家卡。',`<div class="scan-well"><div class="scan-rings">◎</div><strong>等待玩家卡</strong><p class="hint" style="margin:8px 0 0">已有 NFC 读卡器？直接刷卡。<br>没有设备，可以点击下方模拟玩家卡试用。</p></div><div class="spacer"></div><div class="player-list">${ps.map(p=>`<button class="player-choice" data-action="login-sim" data-id="${p.player_id}">${avatar(publicProfile(p),'hud-avatar')}<span><strong>${esc(p.nickname)}</strong><small>${names[p.extensions.web.skin]} · ${p.extensions.web.simulated?'模拟玩家卡':'本机已识别的玩家卡'} · ${p.collection.length} 位伙伴</small></span><span class="choice-arrow">模拟刷卡 ↗</span></button>`).join('')}</div><div class="spacer"></div><div class="actions">${btn('new-demo','＋ 新建模拟玩家卡','primary')}${btn('readers-modal','连接读卡器','light')}</div><p class="hint" style="margin:16px 0 0">模拟登录用于测试，不是安全认证。实体卡的 ID 也不应作为保密凭据。</p>`);}
function skinChoices(){return`<div class="skin-grid">${Object.keys(names).map(n=>`<button class="skin-choice ${draftSkin===n?'selected':''}" data-action="skin" data-value="${n}"><img src="${A['char'+n]}" alt="${esc(names[n])}"><br>${n}</button>`).join('')}</div>`;}
function blankCardGuide(e){
  const kind=e.ndef||'unknown';
  const uid=esc(e.uid||'');
  const canWrite=!!readerInfo.canWrite;
  if(kind==='error'){toast('读卡失败。卡还在感应区时再试一次；这不是空白卡。',true);return;}
  if(kind==='unsupported'){toast('读到 UID，但这张卡不是可写的 NTAG 用户区。只能使用 UID，不会写卡。',true);newPlayerDialog(e);return;}
  if(kind==='foreign'){
    modalOpen('这张卡已有别的内容',`<p class="modal-copy">UID <span class="mono">${uid}</span> 上已有不是本游戏的 NDEF。不会静默覆盖。</p><div class="notice">本机绑定只记住 UID，卡上的内容保持原样。</div><div class="spacer"></div><div class="actions">${btn('bind-local','只在本机绑定，不写卡','primary')}${canWrite?btn('overwrite-ask','我确认要覆盖卡上的内容','light'):''}</div>`);
    registration=e;return;
  }
  if(kind==='unformatted'){
    modalOpen('这张卡还没有 NDEF 格式',`<p class="modal-copy">UID <span class="mono">${uid}</span> 没有标准的 Capability Container。固件不会猜测容量，也不会写 CC、锁定位或 UID。</p><div class="notice">可以只在这台浏览器记住这张 UID。那不等于卡已经被写入。</div><div class="spacer"></div>${btn('bind-local','只在本机绑定，不写卡','primary full')}`);
    registration=e;return;
  }
  if(kind==='blank'){
    modalOpen('这张卡还是空白的',`<p class="modal-copy">UID <span class="mono">${uid}</span> 可以读到，但没有 PULSE 身份。空白卡不会被当成已经有玩家数据。</p><div class="notice">本机绑定：只在浏览器里记住 UID，卡保持空白。<br>${canWrite?'写入身份：确认后才把玩家 ID、卡面和昵称写进 NTAG 用户区，写完会读回核对。不写密码，不改 UID。':'当前桥没有开放写卡，所以这里只能本机绑定。'}</div><div class="spacer"></div><div class="actions">${btn('bind-local','只在本机绑定，不写卡','primary')}${canWrite?btn('write-blank','预览并写入玩家身份','light'):''}</div>`);
    registration=e;return;
  }
  modalOpen('这张卡还没有本机身份',`<p class="modal-copy">UID <span class="mono">${uid}</span>。连接的桥没有报告 NDEF 类型（旧固件会这样）。不要把它当成已经确认的空白卡。</p><div class="notice">下一步只在本机绑定 UID，不会写卡。</div><div class="spacer"></div>${btn('bind-local','只在本机绑定，不写卡','primary full')}`);
  registration=e;
}
function newPlayerDialog(event=null){registration=event;draftSkin='01';modalOpen(event?'这张卡还没有身份。':'制作一张模拟玩家卡。',`<p class="modal-copy">01–09 是九种玩家卡外观，每张新玩家卡都会获得独立的玩家 ID。${event?'这一步只在本机绑定卡号，不会改写实体卡。':'模拟卡保存在当前浏览器，可以用来试玩全部流程。'}</p>${event?`<div class="notice">读到卡号：<span class="mono">${esc(event.uid||event.descriptor?.id)}</span></div><div class="spacer"></div>`:''}<label>玩家昵称<input id="new-name" maxlength="24" placeholder="给自己起个名字" value="${event?'':'玩家 '+(db.profiles.length+1)}"></label><label>玩家卡面 <span class="muted">01–09</span></label><div id="skin-picker">${skinChoices()}</div><div class="spacer"></div>${btn('create-player',event?'绑定为玩家卡':'创建并登录','primary full')}${event?`<div class="rule"></div><div class="spread"><span class="hint">它其实是一张英雄卡？</span>${btn('bind-hero-dialog','登记为英雄卡','small light')}</div>`:''}`);registration=event;}
async function login(p,simulated=false){if(network&&screen!=='battle'){network.close();network=null;netRole=null;netOutput='';netInfo={state:'idle',message:'玩家切换，原连接已取消'};}if(mode==='hotseat'&&view?.phase==='playing'&&screen==='battle'&&identities[view.turn_player].player_id!==p.player_id){toast('请刷 '+identities[view.turn_player].name+' 的玩家卡',true);return;}profileId=p.player_id;rememberPlayer();draftDeck=null;if(mode==='hotseat'&&view?.phase==='playing'&&screen==='battle'){const expected=view.turn_player;unlocked=expected;seat=expected;view=E.projectView(authority.state,seat);closeModal();render();return;}closeModal();const after=profileAfter;profileAfter=null;render();toast((simulated?'模拟刷卡成功 · ':'登录成功 · ')+p.nickname);if(after==='ai')await startAI();else if(after==='hotseat')hotseatSetup();else if(after==='online')openNetwork();}
async function ensurePlayer(){let p=current();if(p)return p;const key='demo:player-'+id();p=await db.createPlayer({name:'玩家 '+(db.profiles.length+1),skin:'01',key,simulated:true});profileId=p.player_id;rememberPlayer();return p;}
function simCards(){modalOpen('模拟卡盒',`<p class="modal-copy">这里是没有读卡器时的测试入口。每张模拟英雄卡也遵守“同一玩家，每天一次”的限制，日期按 UTC+8 计算。</p><div class="section-label">Player cards / 玩家卡</div><div class="player-list">${db.profiles.map(p=>`<button class="player-choice" data-action="login-sim" data-id="${p.player_id}">${avatar(publicProfile(p),'hud-avatar')}<span><strong>${esc(p.nickname)}</strong><small>模拟刷玩家卡登录</small></span><span class="choice-arrow">◎</span></button>`).join('')}</div><div class="spacer"></div>${btn('new-demo','新建玩家卡','small light')}<div class="section-label">Hero cards / 英雄卡</div><div class="mock-deck">${P.cards.filter(c=>c.kind==='unit').map(c=>`<button class="mock-card" data-action="demo-hero" data-id="${c.template_id}"><img src="${A['char'+T[c.template_id].asset]}" alt=""><strong>${T[c.template_id].asset} · ${esc(T[c.template_id].name.split(' ')[0])}</strong><div class="muted" style="margin-top:4px">每日盲盒</div></button>`).join('')}</div><div class="spacer"></div><div class="notice">卡面不决定盲盒结果。若要演示指定角色卡，请到“读卡器”登记一张卡为“指定角色”；已有登记会被保留。</div>`,true,'SIMULATION / 开发测试');}
function cardDetail(tid){const c=D[tid],p=current(),owned=p?.collection.find(i=>i.template_id===tid);modalOpen(T[tid].name,`<div class="reward-card">${cardHTML(tid)}</div><p class="reward-sub">${esc(T[tid].lore)}</p><div class="notice">${effectText(c)}。${c.effect.op==='BOOST'?'只能选择此前已在场的己方角色，不能增强刚部署的自己。':c.effect.op==='DAMAGE'?'目标战力最低降到 0，仍然留在战场。稳定目标不变，护盾目标只消耗护盾。':c.effect.op==='SELF_BOOST_OTHER_ROW'?'只在部署时检查；同一排的友军不触发。':'该能力不会随重复抽卡增强。'}</div><div class="spacer"></div>${owned?`<p class="hint">已获得 ${owned.draw_count} 次 · 当前外观：${owned.skin_id==='ink'?'墨色':'原色'}</p>${btn('ink',owned.unlocked_skins.includes('ink')?'切换原色 / 墨色':'50 碎片 · 解锁墨色','full light',`data-id="${tid}"`)}`:`<p class="hint">${c.kind==='tactic'?'公共战术，所有玩家都可使用。':'尚未收藏；标准对战可以借用，刷英雄卡可获取自己的收藏。'}</p>`}`);}
function hotseatSetup(){if(!current()){players('hotseat');return;}const ps=db.profiles;modalOpen('一台设备，两位玩家。',`<p class="modal-copy">先准备两张不同的玩家卡。每次轮到另一位玩家，手牌会遮住，刷该玩家卡后才能继续。</p><label>玩家 A<select id="seat-a">${ps.map(p=>`<option value="${p.player_id}" ${p.player_id===profileId?'selected':''}>${esc(p.nickname)} · ${names[p.extensions.web.skin]}</option>`).join('')}</select></label><label>玩家 B<select id="seat-b">${ps.filter(p=>p.player_id!==profileId).map(p=>`<option value="${p.player_id}">${esc(p.nickname)} · ${names[p.extensions.web.skin]}</option>`).join('')}</select></label><div class="spacer"></div><div class="actions">${btn('start-hotseat','开始面对面对决','primary',ps.length<2?'disabled':'')}${btn('add-second','＋ 准备另一张模拟卡','light')}</div><div class="spacer"></div><div class="notice">已登记实体玩家可直接在大厅刷卡。双方采用各自保存的十张卡组；模拟卡也会经过交接屏。</div>`);}
async function startAI(){const p=await ensurePlayer();await startLocal('ai',[publicProfile(p),{player_id:'00000000-0000-4000-8000-000000000001',name:'PULSE 训练机',skin:'09',simulated:true}],[p.decks[0].template_ids,P.starter_deck.slice()]);}
async function startLocal(nextMode,who,decks){const previous={mode,authority,view,identities,seat,unlocked,screen,logs};closeModal();network?.close();network=null;clearTimeout(aiTimer);mode=nextMode;aiBlocked=false;identities=who;seat=0;unlocked=nextMode==='hotseat'?null:0;const seed=new Uint32Array(1);crypto.getRandomValues(seed);authority=new E.Authority(P,E.newMatch(P,id(),who.map(p=>p.player_id),decks,seed[0]));view=E.projectView(authority.state,seat);logs=['对局开始。十张牌，贯穿整场。'];selected=null;matchEvents=[];screen='battle';try{await persistMatch();}catch(e){({mode,authority,view,identities,seat,unlocked,screen,logs}=previous);render();throw e;}render();scheduleAI();}
async function persistMatch(){if(authority&&['ai','hotseat'].includes(mode)){await db.saveMatch({content_hash:HASH,mode,state:authority.state,ledger:authority.exportLedger(),identities,logs:logs.slice(-30)});}}
function mine(){return view?.players[seat];}
function canAct(){return screen==='battle'&&view?.phase==='playing'&&view.turn_player===seat&&!busy&&(mode!=='hotseat'||unlocked===seat)&&(mode!=='online'||network?.isOpen);}
function battleHeaderPlayer(which){const p=view.players[which],who=identities[which],score=view.scores[which];return`<div class="player-hud"><div class="identity">${avatar(who,'hud-avatar')}<div><div class="hud-name">${esc(who.name)} ${which===seat?'<span class="badge gray" style="font-size:8px;padding:2px 5px">你</span>':''}</div><div class="hud-caption"><span>手牌 ${p.hand_count}</span><span>已出 ${p.played_count}/5</span>${p.passed?'<span style="color:#ba7143">已停牌</span>':view.turn_player===which?'<span style="color:var(--mint)">● 行动中</span>':''}</div></div></div><div class="hud-score"><div><div class="gems">${[0,1,2,3].map(n=>`<i class="gem ${n<p.match_points?'won':''}"></i>`).join('')}</div><div style="font-size:8px;color:#8c9682;margin-top:6px;text-align:right">${p.match_points} 积分</div></div><span class="score-number">${score}</span></div></div>`;}
function targets(){if(!selected)return[];const h=mine()?.hand?.find(c=>c.instance_id===selected);if(!h)return[];const op=D[h.template_id].effect.op;return op==='BOOST'?mine().board:op==='DAMAGE'?view.players[1-seat].board:[];}
function lane(which,row){const units=view.players[which].board.filter(u=>u.row===row),legal=selected&&canAct()&&which===seat&&D[mine().hand.find(c=>c.instance_id===selected)?.template_id]?.allowed_rows.includes(row),targetIds=canAct()?targets().map(c=>c.instance_id):[];return`<div class="lane ${legal?'placeable':''} ${legal&&selectedRow===row?'chosen':''}" ${legal?`data-action="row" data-value="${row}"`:''}><div class="lane-label"><span>${row==='front'?'前 排':'后 排'}</span><strong>${units.reduce((a,u)=>a+u.power,0)}</strong></div><div class="lane-cards">${units.map(u=>`<button class="board-card ${u.stable?'stable':''} ${targetIds.includes(u.instance_id)?'targetable':''} ${selectedTarget===u.instance_id?'targeted':''}" data-action="${targetIds.includes(u.instance_id)?'target':'board-detail'}" data-id="${esc(u.instance_id)}" data-template="${u.template_id}" title="${esc(T[u.template_id].name+' · 战力 '+u.power+(u.stable?' · 稳定':u.shield?' · 护盾':''))}" aria-label="${esc(T[u.template_id].name+' 战力 '+u.power+(targetIds.includes(u.instance_id)?' 可选为技能目标':''))}"><span class="unit-power" style="${u.power>u.base_power?'background:var(--mint)':u.power<u.base_power?'background:#b9533c':''}">${u.power}</span><img src="${A['char'+T[u.template_id].asset]}" alt=""><span class="unit-trait">${u.stable?'◆':u.shield?'◇':''}</span></button>`).join('')}${!units.length?`<span class="lane-placeholder">${legal?'点击部署到'+(row==='front'?'前排':'后排'):which===seat?'等待你的伙伴入场':'对方尚未部署'}</span>`:''}</div></div>`;}
function selectionPanel(){const hand=mine()?.hand||[],card=hand.find(c=>c.instance_id===selected);if(!card)return`<div class="selection-panel"><div class="selection-empty"><div class="empty-icon">▱</div><p>${view.phase==='finished'?'这场对战已经结束。查看战报，或再来一场。':aiBlocked?'保存失败，电脑回合已暂停。请释放存储空间或导出备份，然后点击重试。':canAct()?'点选一张手牌，决定它该在哪里、何时登场。':'观察战场，想一想下一手。'}</p>${aiBlocked?btn('retry-ai','重试电脑回合','small light'):''}</div></div>`;const c=D[card.template_id],list=targets(),target=list.find(u=>u.instance_id===selectedTarget),needTarget=list.length>0&&(c.effect.op==='BOOST'||c.effect.op==='DAMAGE'),noTargetTactic=c.kind==='tactic'&&!list.length;return`<div class="selection-panel">${cardHTML(card.template_id)}<h4>${esc(T[card.template_id].name)}</h4><p>${effectText(c)}</p>${c.kind==='unit'?`<div class="row-choices">${c.allowed_rows.map(r=>`<button class="${selectedRow===r?'selected':''}" data-action="row" data-value="${r}">${r==='front'?'前排':'后排'}</button>`).join('')}</div>`:''}<p style="color:${target?.stable?'#b47d3f':'var(--mint)'}">${noTargetTactic?'没有可用目标，战术牌暂时不能打出。':needTarget?(target?`目标：${esc(T[target.template_id].name)}${target.stable?'（稳定：技能不会生效）':target.shield&&c.effect.op==='DAMAGE'?'（消耗护盾，不扣战力）':''}`:'请点击战场上高亮的'+(c.effect.op==='BOOST'?'己方':'敌方')+'角色'):['BOOST','DAMAGE'].includes(c.effect.op)?'暂无目标，可直接部署，技能不触发。':c.effect.op==='SELF_BOOST_OTHER_ROW'?(mine().board.some(u=>u.row!==selectedRow)?'另一排有友军：部署后战力 +2':'另一排还没有友军，不触发联结。'):'准备部署。'}</p>${btn('deploy',c.kind==='unit'?'部署角色　↗':'执行战术　↗','primary full',!canAct()||noTargetTactic||needTarget&&!selectedTarget?'disabled':'')}</div>`;}
function battle(){if(!view)return home();const hidden=mode==='hotseat'&&unlocked===null&&view.phase==='playing',my=mine(),other=1-seat,acting=canAct(),roundMsg=view.phase==='finished'?'对局已结束':hidden?'等待玩家卡':acting?'轮到你了':mode==='ai'?'训练机思考中…':'等待对方出牌';return`<main class="battle-shell"><div class="battle-toolbar"><div class="battle-title"><span class="eyebrow" style="font-size:9px">${mode==='ai'?'TRAINING':mode==='hotseat'?'LOCAL DUEL':'ONLINE DUEL'}</span><span>${mode==='online'?(network?.isOpen?'● 连接正常':'○ 连接中断'):mode==='hotseat'?'本地双人':'人机练习'}</span></div><div class="rounds">${[1,2,3].map(n=>{const r=view.round_results.find(x=>x.round_index===n);return`<span class="round-pill ${r?'done':view.round_index===n?'active':''}">${r?`${n}局 ${r.scores[seat]}:${r.scores[other]}`:`第 ${n} 局`}</span>`;}).join('')}</div><button class="text-btn" style="font-size:10px;padding:0" data-action="battle-menu">菜单 ···</button></div><div class="battle-layout"><div class="battle-main"><section class="arena" aria-label="对战战场">${battleHeaderPlayer(other)}<div class="lanes">${lane(other,'rear')}${lane(other,'front')}</div><div class="center-line">PULSE / TWO FRONTS, ONE CHOICE</div><div class="lanes">${lane(seat,'front')}${lane(seat,'rear')}</div>${battleHeaderPlayer(seat)}</section><section class="hand-section" aria-label="你的手牌"><div class="hand-heading"><strong>你的手牌 <span class="muted">/ ${my.hand_count}</span></strong><span>局间不补牌，留一点给下一局。</span></div><div class="hand-row">${hidden?Array.from({length:Math.min(my.hand_count,10)},()=>'<div class="hand-back">PULSE</div>').join(''):(my.hand||[]).map(c=>cardHTML(c.template_id,{action:'select-card',instance:c.instance_id,selected:c.instance_id===selected,disabled:!acting})).join('')}${!my.hand_count?'<div class="hand-empty">手牌已经用尽。</div>':''}</div></section></div><aside class="battle-aside"><div class="turn-box"><div class="eyebrow">ROUND ${view.round_index} / ${view.phase==='finished'?'COMPLETE':acting?'YOUR MOVE':'STAND BY'}</div><h3>${roundMsg}</h3><p>${view.phase==='finished'?'最后的积分，记录这一场取舍。':mode==='online'&&!network?.isOpen?'连接已中断，暂不能出牌。可从菜单离开并重新连接。':acting?`本局还可出 ${5-my.played_count} 张。<br>也可以停牌，把机会留到下一局。`:'对方的手牌始终保密。<br>看战力，也留意剩余牌数。'}</p></div>${selectionPanel()}${view.phase==='finished'?btn('show-result','查看对战结果','primary full'):btn('pass-dialog','本局停牌　PASS','full pass-btn',acting?'':'disabled')}<div class="battle-log" aria-label="对战记录"><h4>FIELD LOG / 战场记录</h4>${logs.slice(-6).reverse().map((l,i)=>`<div class="log-entry ${!i?'latest':''}">${esc(l)}</div>`).join('')}</div></aside></div>${hidden?`<div class="handoff"><div class="handoff-inner"><div class="eyebrow">PASS THE DEVICE / 交接设备</div><div class="spacer"></div>${avatar(identities[view.turn_player],'hud-avatar')}<h2>请交给 ${esc(identities[view.turn_player].name)}</h2><p>双方手牌已遮住。<br>刷这位玩家的卡，继续你的回合。</p>${btn('unlock-demo','◎ 模拟刷卡 · '+esc(identities[view.turn_player].name),'light full')}<p style="font-size:10px;margin-top:12px">上方按钮是明确的模拟登录入口。实体读卡器也可直接刷卡。</p><input id="handoff-uid" class="uid-input" placeholder="键盘式读卡器：刷卡后回车" autocomplete="off" aria-label="交接时读取玩家卡号"></div></div>`:''}</main>`;}
function addEvents(events){for(const e of events||[]){if(e.kind==='played')logs.push(`${identities[e.actor]?.name||'玩家'} 部署 ${T[e.card.template_id]?.name||e.card.template_id}`);if(e.kind==='pass')logs.push(`${identities[e.actor]?.name||'玩家'} 主动停牌`);if(e.kind==='power')logs.push(`战力 ${e.delta>=0?'+':''}${e.delta}`);if(e.kind==='shield_consumed')logs.push('护盾抵消了这一次干扰');if(e.kind==='immune')logs.push('稳定生效：战力保持不变');if(e.kind==='round_ended')logs.push(`第 ${e.round_index} 局 ${e.scores[0]} : ${e.scores[1]} · ${e.winner===null?'平局':identities[e.winner]?.name+' 胜出'}`);if(e.kind==='auto_pass')logs.push(`${identities[e.actor]?.name||'玩家'} 自动停牌`);}logs=logs.slice(-40);}
function selectCard(instance){if(!canAct())return;const c=mine().hand.find(x=>x.instance_id===instance);if(!c)return;selected=instance;selectedRow=D[c.template_id].allowed_rows[0]||null;selectedTarget=null;render();}
function command(kind){return{match_id:view.match_id,action_id:id(),expected_revision:view.revision,kind,card_instance_id:kind==='play'?selected:null,row:kind==='play'?selectedRow:null,target_instance_id:kind==='play'?selectedTarget:null};}
async function execute(cmd,actor=seat){if(busy)return;busy=true;try{if(mode==='online'){network.sendAction(cmd);render();return;}const old=authority.state,oldLedger=authority.exportLedger(),oldLogs=logs.slice(),result=authority.submit(actor,cmd);if(result.status!=='accepted')throw new E.PCGError(result.error_code);addEvents(result.events);try{await persistMatch();}catch(e){authority=new E.Authority(P,old,oldLedger);logs=oldLogs;throw e;}selected=null;selectedTarget=null;selectedRow=null;if(mode==='hotseat'){seat=authority.state.turn_player??seat;unlocked=null;}view=E.projectView(authority.state,seat);matchEvents=result.events;busy=false;render();if(view.phase==='finished'){await db.recordMatch(identities.map(p=>p.player_id),authority.state,mode==='ai'?[0]:[0,1]);showResult();}else if(result.events.some(e=>e.kind==='round_ended')){const r=result.events.filter(e=>e.kind==='round_ended').at(-1);toast(`第 ${r.round_index} 局结算 ${r.scores[0]} : ${r.scores[1]}，未出的牌保留。`);}scheduleAI();}catch(e){busy=false;if(mode==='ai'&&actor===1)aiBlocked=true;fail(e);render();}}
function scheduleAI(){clearTimeout(aiTimer);if(mode==='ai'&&!aiBlocked&&view?.phase==='playing'&&view.turn_player===1){aiTimer=setTimeout(()=>{if(mode==='ai'&&view?.turn_player===1){const action=E.chooseAction(P,E.projectView(authority.state,1),1);execute(action,1);}},850);}}
function showResult(){if(!view||view.phase!=='finished')return;const outcome=view.winner===null?'势均力敌，握手言和。':view.winner===seat?'漂亮，拿下这场对决。':'这一局，留给下次翻盘。';modalOpen('对战结束',`<div class="result-win">${view.winner===null?'平局':esc(identities[view.winner].name)+' 胜出'}</div><p class="reward-sub">${outcome}</p><table class="result-table"><thead><tr><th>回合</th><th>${esc(identities[0].name)}</th><th>${esc(identities[1].name)}</th></tr></thead><tbody>${view.round_results.map(r=>`<tr><td>第 ${r.round_index} 局</td><td>${r.scores[0]} ${r.winner===0?'✓':''}</td><td>${r.scores[1]} ${r.winner===1?'✓':''}</td></tr>`).join('')}<tr><th>最终积分</th><th>${view.players[0].match_points}</th><th>${view.players[1].match_points}</th></tr></tbody></table><div class="actions">${btn('leave-battle','返回大厅','primary')}${mode==='ai'?btn('start-ai','再练一场','light'):btn('close-modal','查看战场记录','light')}</div><p class="hint" style="margin:18px 0 0">结果已记入当前浏览器的玩家资料，胜负不会改变卡牌战力。</p>`);}
function openNetwork(){if(!current()){players('online');return;}screen='network';render();}
function networkPage(){return`<main class="page"><div class="page-heading"><div><div class="eyebrow">PEER TO PEER / 远程交锋</div><h1>隔着距离，坐在同一张桌前。</h1><p>一人创建邀请，另一人生成回复。交换两段连接码后，浏览器直接对战。</p></div><span class="badge ${network?.isOpen?'':'gray'}">${esc(netInfo.message||'尚未连接')}</span></div><div class="columns"><section class="pane"><h3>01 / 建立连接</h3><p>双方使用同一个版本，并先登录各自的玩家卡。</p><div class="identity-preview">${avatar(publicProfile(current()),'hud-avatar')}<div><h3>${esc(current().nickname)}</h3><small class="muted">使用已保存的十张编队 · ${names[current().extensions.web.skin]}</small></div></div><div class="spacer"></div><div class="actions">${btn('rtc-offer','我是房主 · 创建邀请','primary',netInfo.state==='gathering'?'disabled':'')}${btn('rtc-join-focus','我有邀请 · 加入','light')}</div><div class="spacer"></div><label id="signal-label">${netRole==='host'?'粘贴对方的回复码':'粘贴房主的邀请码'}<textarea id="remote-signal" class="codebox" placeholder="PCGRTC1.…" spellcheck="false"></textarea></label>${btn('rtc-accept',netRole==='host'?'接收回复，开始连接':'生成回复码','full green')}<div class="spacer"></div><details class="faq-item"><summary>网络设置 · STUN / TURN</summary><p>本地双标签页或同一局域网可选择“仅本地”。公网默认使用 Google STUN 发现地址；无法穿透时需要自备 TURN 中继。</p><label>连接方式<select id="ice-mode"><option value="public" ${netIceMode==='public'?'selected':''}>公网 · 默认 STUN</option><option value="lan" ${netIceMode==='lan'?'selected':''}>仅本地 / 局域网</option><option value="custom" ${netIceMode==='custom'?'selected':''}>自定义 ICE 配置</option></select></label><label>自定义 iceServers JSON<textarea id="ice-json" class="codebox" placeholder='[{"urls":"turn:your-server:3478","username":"...","credential":"..."}]'></textarea></label><p class="hint">凭据只用于本次连接，不写入本地存档。跨网连接不保证成功。</p></details></section><section class="pane"><h3>02 / 把连接码发给对方</h3><p>${netOutputKind==='answer'?'把下面的回复码发回给房主。对方接收后，两端会自动进入战场。':'房主创建邀请后，将连接码复制给另一位玩家；收到对方回复后粘贴到左侧。'}</p><label>本机生成的${netOutputKind==='answer'?'回复':'邀请'}码<textarea id="local-signal" class="codebox" readonly placeholder="连接码会显示在这里…">${esc(netOutput)}</textarea></label><div class="actions">${btn('rtc-copy','复制连接码','light',!netOutput?'disabled':'')}${btn('rtc-cancel','取消连接','ghost',!network?'disabled':'')}</div><div class="spacer"></div><div class="notice" id="network-status">${esc(netInfo.message||'等待创建邀请或粘贴邀请。')}</div><div class="rule"></div><div class="step-line"><span class="step-num">1</span><span>房主把<b>邀请码</b>发给另一位玩家。</span></div><div class="step-line"><span class="step-num">2</span><span>另一位玩家粘贴邀请，生成<b>回复码</b>发回。</span></div><div class="step-line"><span class="step-num">3</span><span>房主粘贴回复。数据通道接通后自动开始。</span></div><p class="protocol-chip">规则 pcg.core.v1<br>卡包 m5.web.assets.v1 · ${HASH.slice(0,16)}…</p><p class="hint">对方只能收到你的手牌数量。房主负责结算，适合朋友之间对战。刷新会丢失在线房间；断开连接后不会判负或伪造胜利。</p></section></div></main>`;}
function iceConfig(){const mode=$('#ice-mode')?.value||netIceMode;netIceMode=mode;netIceText=$('#ice-json')?.value||netIceText;if(mode==='lan')return[];if(mode==='custom'){const v=JSON.parse(netIceText);if(!Array.isArray(v)||v.length>8)throw new Error('请输入最多 8 项的 iceServers 数组');return v;}return undefined;}
function makeNetwork(ice){network?.close();const p=current();netLocal={player_id:p.player_id,name:p.nickname,skin:p.extensions.web.skin,deck:p.decks[0].template_ids.slice()};network=new g.PCGNet.GameSession({pack:P,local:netLocal,iceServers:ice,onState:info=>{netInfo=info;const el=$('#network-status');if(el)el.textContent=info.message;if(mode==='online'&&screen==='battle'){busy=false;render();}},onError:e=>{busy=false;netInfo={state:'failed',message:message(e)};fail(e);if(screen==='battle'||screen==='network')render();},onUpdate:update=>{const first=mode!=='online'||!view||view.match_id!==update.view.match_id;mode='online';authority=null;seat=update.seat;view=update.view;identities=update.identities;profileId=identities[seat].player_id;rememberPlayer();unlocked=seat;selected=null;selectedTarget=null;selectedRow=null;busy=false;if(first)logs=['数据通道已接通，对局开始。'];addEvents(update.events||[]);screen='battle';closeModal();render();if(view.phase==='finished'){db.recordMatch(identities.map(p=>p.player_id),view,[seat]).then(()=>showResult()).catch(fail);}}});return network;}
function readerPage(){const p=current(),caps=g.PCGReaders.capabilities?.()||{},bindings=Object.entries(db.data.bindings);return`<main class="page"><div class="page-heading"><div><div class="eyebrow">TAP TO PLAY / 连接读卡器</div><h1>一张卡，一个入口。</h1><p>玩家卡负责身份，英雄卡负责招募。刷卡成功后会显示卡号和识别结果。</p></div>${btn('simcards','打开模拟卡盒','light')}</div><div class="columns aside"><section class="pane"><div class="device-strip"><span class="scan-rings" style="margin:0">◎</span><div><strong>${esc(readerInfo.message)}</strong><small>${lastScan?'最近读取：'+esc(lastScan.uid||lastScan.descriptor?.id||'NDEF'):isSecureContext?'当前页面处于安全上下文':'请从 localhost 或 HTTPS 打开本页'}</small></div></div><div class="reader-options"><div class="reader-option"><h4>M5Dial 读卡桥 <span class="badge gray">Web Serial</span></h4><p>用这个按钮。选择器里应出现 Espressif Device 或 PULSE M5Dial NFC（303A:4001，例如 cu.usbmodem1234561）。「已配对」只表示浏览器以前授权过，顶栏灯要握手成功才变绿。不要选 USB JTAG（303A:1001，cu.usbmodem101）。</p>${btn('connect-m5dial','连接 M5Dial','small primary',!navigator.serial?'disabled':'')}</div><div class="reader-option"><h4>WebUSB 协议桥 <span class="badge gray">USB</span></h4><p>这是另一个入口，只列出 class 0xFF 的厂商接口。M5Dial 的 CDC 是 class 0x02，不会出现在这个列表里。网卡、扩展坞或另一台 JTAG 出现在这里是正常的。</p>${btn('connect-usb','连接 USB 协议桥','small light',!navigator.usb?'disabled':'')}</div><div class="reader-option"><h4>USB / 蓝牙键盘式读卡器 <span class="badge">无需驱动 API</span></h4><p>点击卡号框，再刷卡并回车。读卡器需输出 UID 的十六进制原始字节顺序，不能是十进制或反序卡号。</p><div class="actions"><input id="keyboard-uid" class="uid-input" style="flex:1;min-width:180px" placeholder="UID，例如 04:A1:B2:C3:D4:E5:F6" autocomplete="off">${btn('read-keyboard','读取','small green')}</div></div><div class="reader-option"><h4>其他串口桥 / ESP32 + PN532 <span class="badge gray">Web Serial</span></h4><p>不按 PID 过滤，会同时列出 M5Dial 和另一台 JTAG。M5Dial 请优先用上面的按钮。</p>${btn('connect-serial','连接其他串口桥','small light',!navigator.serial?'disabled':'')}</div><div class="reader-option"><h4>手机内置 NFC <span class="badge gray">Web NFC</span></h4><p>支持 Web NFC 的 Android Chrome 可以读取 NDEF，也能写入玩家身份。iPhone Safari 和桌面浏览器没有这个接口。</p>${btn('connect-nfc','启动手机 NFC','small light',!('NDEFReader'in window)?'disabled':'')}</div></div><div class="spacer"></div>${btn('disconnect-reader','断开读卡器','small ghost')}</section><aside class="pane"><h3>NTAG215 玩家卡</h3><p>504 字节可写区足够存放轻量身份。它的 32 位密码保护不是加密认证，本网页不把卡号或密码当成防复制凭据。</p><div class="notice">01–09：玩家卡外观<br>10–22：角色素材<br>新卡首次刷入后，可选择绑定为玩家卡、盲盒卡或指定角色卡。</div><div class="spacer"></div><h3>写入当前玩家身份</h3><p>只写玩家 ID、卡面编号和版本。不会写入收藏和对战存档，也不会配置密码或永久锁定位。</p>${btn('write-identity',p?'将 '+esc(p.nickname)+' 身份写入卡':'先登录玩家','full light',!p||!readerInfo.canWrite?'disabled':'')}<p class="hint">${readerInfo.canWrite?'写入前会要求你确认卡片；写后请重新刷卡核验。':'请先连接支持写入的 Web NFC 或协议桥。仅 UID 键盘读卡器无法写卡。'}</p><div class="rule"></div><h3>备份与迁移</h3><p>本版完整进度保存在当前浏览器。换设备时请导出 / 导入 JSON 备份；只带玩家卡过去只能恢复身份。</p><div class="actions">${btn('export','导出备份','small green')}${btn('import','导入备份','small light')}</div><div class="rule"></div><div class="hint">本机已登记 ${bindings.length} 张卡 · ${db.profiles.length} 位玩家<br>玩家卡的相同外观不会共用一个玩家 ID。<br>同一 UID 在本机只能登记为一种卡片。</div></aside></div><div class="spacer"></div><details class="faq-item"><summary>为什么我的 USB NFC 读卡器不在设备列表里？</summary><p>WebUSB 不能直接接管所有 USB 类别；常见智能卡 / CCID 接口受浏览器限制。键盘式输出 UID 的型号可以走输入框；ESP32 + PN532 可以使用配套串口桥。通用 PC/SC 读卡器需要另做本机桥接程序，本版没有假装支持。</p></details><details class="faq-item"><summary>能不能靠 NTAG215 防作弊？</summary><p>本地网页和可复制的卡片身份都不能提供强防作弊。每日限制保存在玩家本机资料；清空存储、修改代码或复制身份可能绕过。这里面向朋友之间的休闲对战；更强认证需要支持密码学的卡片及可信验证端。</p></details></main>`;}
const readers=new g.PCGReaders.ReaderManager({onCard:e=>onCard(e).catch(fail),onStatus:s=>{readerInfo=s;const r=$('#reader-state');if(r)r.textContent=g.PCGReaders.connectionLabel(s.state);if(screen==='readers'&&!modal.open)render();}});
function cardKey(e){if(!e.uid)throw new Error('读卡器没有返回 UID，无法给未登记卡片绑定身份');return'uid:'+g.PCGReaders.normalizeUID(e.uid);}
async function onCard(e){lastScan=e;const descriptor=e.descriptor;let key=e.uid?cardKey(e):null,binding=key?db.binding(key):null;if(descriptor?.type==='player'){if(binding&&binding.type!=='player')throw new Error('卡内身份与本机英雄卡登记冲突，请用另一张卡');const p=await db.createPlayer({id:descriptor.id,name:descriptor.name||names[descriptor.skin]+' 玩家',skin:descriptor.skin,key,simulated:false});if(screen==='battle'&&view?.phase==='playing'&&mode!=='hotseat'){if(p.player_id!==identities[seat].player_id)throw new Error('对战期间不能切换到另一位玩家');toast('玩家身份已确认');return;}await login(p);return;}
 if(binding?.type==='player'){const p=db.getProfile(binding.player_id);if(screen==='battle'&&view?.phase==='playing'&&mode!=='hotseat'){if(p.player_id!==identities[seat].player_id)throw new Error('对战期间不能切换玩家');toast('玩家身份已确认');return;}await login(p);return;}
 if(descriptor?.type==='hero'||binding?.type==='hero'){const hero=descriptor?.type==='hero'?{hero_card_id:'issued:'+descriptor.id,mode:descriptor.mode,template_id:descriptor.template_id}:{hero_card_id:E.heroIdFromUID(e.tech||'nfc-a',e.uid),mode:binding.mode,template_id:binding.template_id};await heroScan(hero);return;}
 if(screen==='battle'&&view?.phase==='playing')throw new Error('这张卡尚未登记，请结束对局后在大厅绑定');blankCardGuide(e);}
async function heroScan(hero){const p=current();if(!p)throw new Error('请先刷玩家卡登录，再刷英雄卡');if(screen==='battle'&&view?.phase==='playing'){const tid=hero.mode==='fixed'?hero.template_id:p.day_ledger.claims.find(c=>c.hero_card_id===hero.hero_card_id)?.template_id;if(!canAct())throw new Error('还没轮到你，或需要先刷玩家卡揭开手牌');const c=mine().hand.find(c=>c.template_id===tid);if(!c)throw new Error('这张英雄卡没有对应的可用手牌；对战中不抽盲盒');selectCard(c.instance_id);toast('已选中 '+T[tid].name);return;}const reward=await db.claim(profileId,hero);const c=T[reward.template_id];render();modalOpen(reward.is_duplicate?'熟悉的伙伴，又见面了。':'一位新伙伴，加入你的编队。',`<div class="reward-card shake">${cardHTML(reward.template_id)}</div><h3 class="reward-title">${esc(c.name)}</h3><p class="reward-sub">${reward.is_duplicate?`重复角色已转为 ${reward.shards_delta} 碎片`:'已加入你的收藏 · 标准战力保持一致'}</p><div class="notice">${hero.mode==='fixed'?'指定角色卡':'每日盲盒'} · 此玩家今天已领取这张卡的奖励。<br>领取记录与角色已一并保存到当前浏览器。</div><div class="spacer"></div><div class="actions">${btn('go-collection','查看我的收藏','primary')}${btn('simcards','继续看看卡盒','light')}</div>`,false,'TAP REWARD / 触卡招募');}
function heroBindDialog(){const e=registration;if(!e)return;modalOpen('给这张英雄卡定义奖励。',`<p class="modal-copy">登记保存在本机，不会改写卡片。每位玩家每天对这张卡最多领取一次。</p><label>奖励模式<select id="hero-mode"><option value="blind">盲盒 · 从全部 13 个角色中抽取</option><option value="fixed">指定角色 · 固定获得下方角色</option></select></label><label>指定角色<select id="hero-template">${P.cards.filter(c=>c.kind==='unit').map(c=>`<option value="${c.template_id}">${T[c.template_id].asset} · ${T[c.template_id].name}</option>`).join('')}</select></label><div class="spacer"></div>${btn('bind-hero-confirm','登记并读取这张卡','primary full')}`);registration=e;}
function render(){try{app.innerHTML=header()+(screen==='battle'?battle():screen==='collection'?collection():screen==='network'?networkPage():screen==='readers'?readerPage():home());}catch(e){fail(e);}}
async function navigate(next){if(screen==='battle'&&view?.phase==='playing'&&next!=='battle'){modalOpen('暂时离开战场？',`<p class="modal-copy">${mode==='online'?'离开会关闭当前在线连接，双方需要重新发起对战。':'当前回合已保存在浏览器，之后可以从大厅继续。'}</p><div class="actions">${btn('leave-to','离开战场','primary',`data-page="${next}"`)}${btn('close-modal','继续对战','light')}</div>`);return;}screen=next;draftDeck=null;render();}
async function leave(next='home'){clearTimeout(aiTimer);if(mode==='online'){network?.close();network=null;}mode=null;authority=null;view=null;selected=null;screen=next;closeModal();render();}
async function handle(action,el){switch(action){
 case'nav':return navigate(el.dataset.page);case'close-modal':closeModal();return;case'rules':rules();return;case'players':if(screen==='battle'&&view?.phase==='playing'){toast('请先完成或离开这场对战');return;}players();return;case'new-demo':newPlayerDialog();return;case'skin':draftSkin=el.dataset.value;$('#skin-picker').innerHTML=skinChoices();return;
 case'create-player':{const event=registration,key=event?cardKey(event):'demo:player-'+id(),p=await db.createPlayer({name:$('#new-name').value,skin:draftSkin,key,simulated:!event});await login(p,!event);return;}
 case'login-sim':{const p=db.getProfile(el.dataset.id);if(screen==='battle'&&view?.phase==='playing'&&mode!=='hotseat'){throw new Error('对战期间不能切换玩家');}await login(p,true);return;}
 case'start-ai':await startAI();return;case'hotseat':hotseatSetup();return;case'add-second':{const n=db.profiles.length+1;await db.createPlayer({name:'玩家 '+n,skin:String((n-1)%9+1).padStart(2,'0'),key:'demo:player-'+id(),simulated:true});hotseatSetup();return;}
 case'start-hotseat':{const a=db.getProfile($('#seat-a').value),b=db.getProfile($('#seat-b').value);if(!a||!b||a.player_id===b.player_id)throw new Error('请选择两位不同的玩家');await startLocal('hotseat',[publicProfile(a),publicProfile(b)],[a.decks[0].template_ids,b.decks[0].template_ids]);return;}
 case'unlock-demo':await login(db.getProfile(identities[view.turn_player].player_id),true);return;
 case'resume':{const saved=db.refresh().saved_match;if(!saved)throw new Error('没有可恢复的对局');mode=saved.mode;identities=saved.identities;authority=new E.Authority(P,saved.state,saved.ledger||{});seat=mode==='ai'?0:saved.state.turn_player??0;unlocked=mode==='hotseat'?null:0;profileId=identities[0].player_id;view=E.projectView(authority.state,seat);logs=saved.logs||[];screen='battle';selected=null;render();scheduleAI();return;}
 case'select-card':selectCard(el.dataset.id);return;case'row':selectedRow=el.dataset.value;render();return;case'target':selectedTarget=el.dataset.id;render();return;case'deploy':if(canAct())await execute(command('play'));return;
 case'pass-dialog':if(!canAct())return;modalOpen('把牌留给下一局？',`<p class="modal-copy">本局停牌后无法撤回。对方仍可以继续出牌；双方都停牌才结算。你还剩 ${mine().hand_count} 张手牌，本局战力 ${view.scores[seat]} : ${view.scores[1-seat]}。</p><div class="actions">${btn('confirm-pass','确认停牌','primary')}${btn('close-modal','再想一手','light')}</div>`,false,'PASS / 留牌的艺术');return;
 case'confirm-pass':closeModal();if(canAct())await execute(command('pass'));return;case'show-result':showResult();return;case'retry-ai':aiBlocked=false;scheduleAI();render();return;case'board-detail':cardDetail(el.dataset.template);return;case'card-detail':cardDetail(el.dataset.id);return;
 case'battle-menu':modalOpen('战场菜单',`<div class="actions">${btn('rules','玩法说明','light')}${mode==='online'?btn('resync','重新同步战场','light'):''}${btn('leave-to','返回大厅','primary','data-page="home"')}${btn('close-modal','继续对战','ghost')}</div><div class="spacer"></div><p class="hint">${mode==='online'?'返回大厅会关闭连接；刷新后不能恢复原在线房间。':'对局自动保存，离开后可以从大厅继续。'}<br>规则 pcg.core.v1 · ${HASH.slice(0,16)}</p>`);return;case'resync':network.requestResync();closeModal();return;case'leave-battle':await leave();return;case'leave-to':await leave(el.dataset.page);return;
 case'go-collection':closeModal();screen='collection';draftDeck=null;render();return;case'collection-tab':collectionTab=el.dataset.value;render();return;case'toggle-deck':{const t=el.dataset.id;if(draftDeck.includes(t))draftDeck=draftDeck.filter(x=>x!==t);else{if(draftDeck.length>=10){toast('编队已经有 10 张，请先移出一张');return;}draftDeck.push(t);}render();return;}case'reset-deck':draftDeck=P.starter_deck.slice();render();return;case'save-deck':await db.setDeck(profileId,draftDeck);toast('十张卡的编队已保存');render();return;case'ink':await db.ink(profileId,el.dataset.id);render();cardDetail(el.dataset.id);return;
 case'simcards':simCards();return;case'demo-hero':await heroScan({hero_card_id:'issued:10000000-0000-4000-8000-'+T[el.dataset.id].asset.padStart(12,'0'),mode:'blind'});return;case'bind-hero-dialog':heroBindDialog();return;case'bind-hero-confirm':{const e=registration;await db.bindHero(cardKey(e),$('#hero-mode').value,$('#hero-template').value);closeModal();await onCard(e);return;}
 case'readers-modal':closeModal();screen='readers';render();return;case'connect-m5dial':await readers.connectM5Dial();render();return;case'connect-usb':await readers.connectUSB();render();return;case'connect-serial':await readers.connectSerial();render();return;case'bind-local':{const e=registration;closeModal();if(!e)return;newPlayerDialog(e);return;}case'write-blank':{const e=registration;if(!e)return;const p=current();if(!p){toast('先登录或创建要写入的玩家',true);return;}const descriptor={game:'pcg',v:1,type:'player',id:p.player_id,skin:p.extensions.web.skin,name:p.nickname};modalOpen('确认后才写入这张空白卡',`<p class="modal-copy">将写入 UID <span class="mono">${esc(e.uid)}</span> 的用户区，不会改 UID，不会上锁，不会写密码。</p><pre class="notice">${esc(JSON.stringify(descriptor))}</pre><div class="spacer"></div><div class="actions">${btn('write-blank-go','确认写入并读回核对','primary')}${btn('close-modal','取消','light')}</div>`);return;}case'write-blank-go':{const e=registration,p=current();if(!e||!p)return;const descriptor={game:'pcg',v:1,type:'player',id:p.player_id,skin:p.extensions.web.skin,name:p.nickname};closeModal();toast('正在写入并读回核对…');try{const result=await readers.writePlayer(descriptor,{overwrite:true});toast(result.verified?'写入并读回成功':'桥报告成功，但请再刷一次确认');}catch(err){toast(err.message||'写入没有完成，卡上的内容不应视为已绑定',true);}return;}case'overwrite-ask':modalOpen('再次确认覆盖',`<p class="modal-copy">卡上已有非本游戏内容。只有这一步会替换它。失败、移开卡或容量不够时，绑定不会被标成完成。</p><div class="spacer"></div><div class="actions">${btn('write-blank-go','确认覆盖并读回','primary')}${btn('bind-local','还是只在本机绑定','light')}</div>`);return;case'connect-nfc':await readers.startWebNFC();render();return;case'disconnect-reader':await readers.disconnect();render();return;case'read-keyboard':readers.feedKeyboard($('#keyboard-uid').value);return;
 case'write-identity':modalOpen('只写入玩家身份，确认卡片。',`<p class="modal-copy">即将把 <b>${esc(current().nickname)}</b> 的 ID 和卡面编号写入你接下来贴近的卡。请使用专门用于本游戏的 NTAG215 或其他兼容 NDEF 卡。</p><div class="notice warn">这会替换卡片原有的 NDEF 内容。完整收藏和对局进度仍保存在浏览器；写入身份不会迁移存档。</div><div class="spacer"></div><div class="actions">${btn('write-confirm','确认 · 将身份写入这张卡','primary')}${btn('close-modal','取消','light')}</div>`);return;
 case'write-confirm':{const p=current(),descriptor={game:'pcg',v:1,type:'player',id:p.player_id,skin:p.extensions.web.skin,name:p.nickname};closeModal();toast('请贴近专用玩家卡，等待写入完成…');const result=await readers.writePlayer(descriptor,{overwrite:true});toast(result.verified?'身份写入并读回验证成功':'写入完成，请移开后重新刷卡核验');return;}
 case'export':download('pulse-backup-'+new Date().toISOString().slice(0,10)+'.json',db.export());toast('已生成本机所有玩家的备份文件');return;case'import':$('#import-file').click();return;
 case'online':openNetwork();return;case'rtc-offer':{const ice=iceConfig();netRole='host';netOutput='';netOutputKind='offer';const n=makeNetwork(ice);netInfo={state:'gathering',message:'正在收集连接地址…'};render();netOutput=await n.createOffer();if(screen==='network')render();return;}
 case'rtc-join-focus':netRole='guest';if(network&&!network.isOpen){network.close();network=null;}render();$('#remote-signal').focus();return;
 case'rtc-accept':{const code=$('#remote-signal').value.trim();if(!code)throw new Error('请先粘贴完整的连接码');if(netRole==='host'){if(!network)throw new Error('请先创建邀请');await network.acceptAnswer(code);if(screen==='network')render();}else{const ice=iceConfig();netRole='guest';netOutputKind='answer';const n=makeNetwork(ice);netInfo={state:'gathering',message:'正在生成回复连接码…'};render();netOutput=await n.acceptOffer(code);if(screen==='network')render();}return;}
 case'rtc-copy':try{await navigator.clipboard.writeText(netOutput);toast('连接码已复制');}catch(e){$('#local-signal').select();toast('请按 Ctrl/Cmd+C 复制选中的连接码');}return;case'rtc-cancel':network?.close();network=null;netInfo={state:'idle',message:'已取消连接'};netOutput='';netRole=null;render();return;
 }}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();handle(el.dataset.action,el).catch(fail);});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.classList.contains('uid-input')){e.preventDefault();try{readers.feedKeyboard(e.target.value);e.target.value='';}catch(err){fail(err);}}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>2*1024*1024)throw new Error('备份文件太大');const result=await db.import(await f.text());draftDeck=null;render();toast('备份已导入，更新 '+result.count+' 位玩家；原有较新进度已保留。');}catch(err){fail(err);}});
window.addEventListener('storage',e=>{if(e.key===S.KEY&&screen!=='battle'){try{db.refresh();if(!db.getProfile(profileId))profileId=null;if(!modal.open)render();}catch(err){fail(err);}}});
try{db=new S.DataStore();if(!db.getProfile(profileId))profileId=null;render();}catch(e){app.innerHTML=`<main class="page"><h1>本地存档暂时无法打开。</h1><p>${esc(e.message)}</p><p>原始数据没有被删除。请下载备份，保留后再排查；不要直接清空浏览器数据。</p><button class="btn" id="recover-raw">下载原始存档</button></main>`;$('#recover-raw').onclick=()=>download('pulse-recovery.json',localStorage.getItem(S.KEY)||'');}
})(globalThis);
